import{_ as a,o,c as r,a5 as t}from"./chunks/framework.D2XEhk-n.js";const p=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md","lastUpdated":1790626046000}'),i={name:"reference/glossary.md"};function s(n,e,d,l,h,c){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p><strong>JUCE classes, audio terms, and plug-in jargon in plain English.</strong> Terms are alphabetical; every entry has its own link anchor, and the site search (<kbd>/</kbd> or <kbd>Ctrl</kbd>+<kbd>K</kbd>) finds them too.</p><div class="glossary-index"><a href="#a">A</a><a href="#b">B</a><a href="#c">C</a><a href="#d">D</a><a href="#e">E</a><a href="#f">F</a><a href="#g">G</a><a href="#h">H</a><a href="#i">I</a><a href="#j">J</a><a href="#l">L</a><a href="#m">M</a><a href="#o">O</a><a href="#p">P</a><a href="#r">R</a><a href="#s">S</a><a href="#t">T</a><a href="#u">U</a><a href="#v">V</a><a href="#w">W</a></div><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A {#a}&quot;">​</a></h2><h3 id="aax" tabindex="-1">AAX <a class="header-anchor" href="#aax" aria-label="Permalink to &quot;AAX {#aax}&quot;">​</a></h3><p>Avid Audio eXtension, the plug-in format for <strong>Pro Tools</strong>. JUCE bundles the SDK, but shipping requires signing with PACE tools. → <a href="./../guide/plugin-anatomy.html#formats-at-a-glance">Plug-in formats</a></p><h3 id="abstractfifo" tabindex="-1">AbstractFifo <a class="header-anchor" href="#abstractfifo" aria-label="Permalink to &quot;AbstractFifo {#abstractfifo}&quot;">​</a></h3><p>Manages the read and write positions of a lock-free, single-producer, single-consumer ring buffer. You supply the storage. The standard way to stream data between the audio and GUI threads. <em>juce_core</em></p><h3 id="apvts" tabindex="-1">APVTS (AudioProcessorValueTreeState) <a class="header-anchor" href="#apvts" aria-label="Permalink to &quot;APVTS (AudioProcessorValueTreeState) {#apvts}&quot;">​</a></h3><p>Owns a plug-in&#39;s parameters, keeps them in sync with a <code>ValueTree</code> for saving, and provides attachments that bind widgets to parameters. <em>juce_audio_processors</em> → <a href="./../guide/core-concepts.html#state">State</a></p><h3 id="ara" tabindex="-1">ARA <a class="header-anchor" href="#ara" aria-label="Permalink to &quot;ARA {#ara}&quot;">​</a></h3><p>Audio Random Access, a Celemony-led extension that lets a plug-in (such as Melodyne) see a host&#39;s whole audio clips and timeline, not only the live stream. Supported since JUCE 7.</p><h3 id="attachment" tabindex="-1">Attachment <a class="header-anchor" href="#attachment" aria-label="Permalink to &quot;Attachment {#attachment}&quot;">​</a></h3><p>A small object (<code>SliderAttachment</code>, <code>ButtonAttachment</code>, <code>ComboBoxAttachment</code>, <code>ParameterAttachment</code>) that keeps a UI control and a plug-in parameter in sync in both directions, including host automation and undo gestures.</p><h3 id="au" tabindex="-1">AU / AUv3 <a class="header-anchor" href="#au" aria-label="Permalink to &quot;AU / AUv3 {#au}&quot;">​</a></h3><p>Apple&#39;s <strong>Audio Unit</strong> plug-in formats. AU (v2) is a macOS bundle used by Logic and GarageBand. AUv3 is an app extension, sandboxed, and the only plug-in format on iOS.</p><h3 id="audio-thread" tabindex="-1">Audio thread <a class="header-anchor" href="#audio-thread" aria-label="Permalink to &quot;Audio thread {#audio-thread}&quot;">​</a></h3><p>The high-priority thread, owned by the driver or host, that calls your processing code every block. It must never wait. → <a href="./../guide/core-concepts.html#threads">Threads</a></p><h3 id="audiobuffer" tabindex="-1">AudioBuffer <a class="header-anchor" href="#audiobuffer" aria-label="Permalink to &quot;AudioBuffer {#audiobuffer}&quot;">​</a></h3><p>A multi-channel block of <code>float</code> or <code>double</code> samples, stored as one array per channel (non-interleaved). The main data type passed to <code>processBlock()</code>. <em>juce_audio_basics</em></p><h3 id="audiodevicemanager" tabindex="-1">AudioDeviceManager <a class="header-anchor" href="#audiodevicemanager" aria-label="Permalink to &quot;AudioDeviceManager {#audiodevicemanager}&quot;">​</a></h3><p>Opens, configures, and remembers the audio and MIDI devices for a standalone app, and calls your <code>AudioIODeviceCallback</code>s. <em>juce_audio_devices</em></p><h3 id="audioprocessor" tabindex="-1">AudioProcessor <a class="header-anchor" href="#audioprocessor" aria-label="Permalink to &quot;AudioProcessor {#audioprocessor}&quot;">​</a></h3><p>The abstract base class for anything that processes audio and MIDI in blocks: your plug-in, a node in a graph, or a hosted third-party plug-in. <em>juce_audio_processors_headless</em> → <a href="./../guide/plugin-anatomy.html">Anatomy of a plug-in</a></p><h3 id="audioprocessoreditor" tabindex="-1">AudioProcessorEditor <a class="header-anchor" href="#audioprocessoreditor" aria-label="Permalink to &quot;AudioProcessorEditor {#audioprocessoreditor}&quot;">​</a></h3><p>The <code>Component</code> that forms a plug-in&#39;s GUI. It is created by <code>AudioProcessor::createEditor()</code> and may be destroyed and recreated at any time.</p><h3 id="audioprocessorgraph" tabindex="-1">AudioProcessorGraph <a class="header-anchor" href="#audioprocessorgraph" aria-label="Permalink to &quot;AudioProcessorGraph {#audioprocessorgraph}&quot;">​</a></h3><p>An <code>AudioProcessor</code> that contains other processors joined by audio and MIDI connections. The basis of modular hosts such as the AudioPluginHost.</p><h3 id="audiosource" tabindex="-1">AudioSource <a class="header-anchor" href="#audiosource" aria-label="Permalink to &quot;AudioSource {#audiosource}&quot;">​</a></h3><p>A simpler, pull-based audio interface (<code>prepareToPlay</code> / <code>getNextAudioBlock</code> / <code>releaseResources</code>) used by players, mixers, and file readers. Unlike <code>AudioProcessor</code>, it has no parameters, buses, or MIDI.</p><h2 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to &quot;B {#b}&quot;">​</a></h2><h3 id="block-size" tabindex="-1">Block / block size <a class="header-anchor" href="#block-size" aria-label="Permalink to &quot;Block / block size {#block-size}&quot;">​</a></h3><p>The number of samples processed per callback, for example 64–1024. Smaller blocks mean lower latency but more CPU overhead. <strong>Never assume a fixed size</strong>: hosts may send shorter blocks than <code>prepareToPlay()</code> announced.</p><h3 id="bus" tabindex="-1">Bus <a class="header-anchor" href="#bus" aria-label="Permalink to &quot;Bus {#bus}&quot;">​</a></h3><p>A named group of channels on a processor, such as &quot;Main In&quot; (stereo) or &quot;Sidechain&quot; (mono). Negotiated with the host through <code>BusesProperties</code> and <code>isBusesLayoutSupported()</code>.</p><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C {#c}&quot;">​</a></h2><h3 id="component" tabindex="-1">Component <a class="header-anchor" href="#component" aria-label="Permalink to &quot;Component {#component}&quot;">​</a></h3><p>The base class of every GUI element: a rectangle that paints itself, holds children, and receives mouse and keyboard events. <em>juce_gui_basics</em> → <a href="./../guide/core-concepts.html#components">Components</a></p><h3 id="componentpeer" tabindex="-1">ComponentPeer <a class="header-anchor" href="#componentpeer" aria-label="Permalink to &quot;ComponentPeer {#componentpeer}&quot;">​</a></h3><p>The platform-specific native window behind a top-level <code>Component</code>. Child components don&#39;t have one.</p><h3 id="createpluginfilter" tabindex="-1">createPluginFilter() <a class="header-anchor" href="#createpluginfilter" aria-label="Permalink to &quot;createPluginFilter() {#createpluginfilter}&quot;">​</a></h3><p>The free function every JUCE plug-in must define. It returns a new instance of your <code>AudioProcessor</code>, and the format wrappers call it. (&quot;Filter&quot; is a legacy word for processor.)</p><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D {#d}&quot;">​</a></h2><h3 id="denormals" tabindex="-1">Denormals <a class="header-anchor" href="#denormals" aria-label="Permalink to &quot;Denormals {#denormals}&quot;">​</a></h3><p>Extremely small floating-point numbers that can make CPUs slow down dramatically, typically in decaying filter tails. <code>ScopedNoDenormals</code> at the top of <code>processBlock()</code> switches them off.</p><h3 id="dsp" tabindex="-1">DSP <a class="header-anchor" href="#dsp" aria-label="Permalink to &quot;DSP {#dsp}&quot;">​</a></h3><p>Digital signal processing: the maths applied to audio samples. Also the <code>juce_dsp</code> module.</p><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E {#e}&quot;">​</a></h2><h3 id="exporter" tabindex="-1">Exporter <a class="header-anchor" href="#exporter" aria-label="Permalink to &quot;Exporter {#exporter}&quot;">​</a></h3><p>In the Projucer, a target IDE configuration: Xcode (macOS or iOS), Visual Studio, Android, or Linux Makefile.</p><h2 id="f" tabindex="-1">F <a class="header-anchor" href="#f" aria-label="Permalink to &quot;F {#f}&quot;">​</a></h2><h3 id="floatvectoroperations" tabindex="-1">FloatVectorOperations <a class="header-anchor" href="#floatvectoroperations" aria-label="Permalink to &quot;FloatVectorOperations {#floatvectoroperations}&quot;">​</a></h3><p>SIMD-accelerated functions for whole arrays of samples: add, multiply, copy, clip, find min and max. <em>juce_audio_basics</em></p><h2 id="g" tabindex="-1">G <a class="header-anchor" href="#g" aria-label="Permalink to &quot;G {#g}&quot;">​</a></h2><h3 id="graphics" tabindex="-1">Graphics <a class="header-anchor" href="#graphics" aria-label="Permalink to &quot;Graphics {#graphics}&quot;">​</a></h3><p>The drawing context passed to <code>Component::paint()</code>. It fills, strokes, draws text and images, and clips, independent of the platform renderer. <em>juce_graphics</em></p><h2 id="h" tabindex="-1">H <a class="header-anchor" href="#h" aria-label="Permalink to &quot;H {#h}&quot;">​</a></h2><h3 id="headless" tabindex="-1">Headless <a class="header-anchor" href="#headless" aria-label="Permalink to &quot;Headless {#headless}&quot;">​</a></h3><p>Running without a display or GUI, for example on a server, in CI, or on embedded Linux. JUCE 6 added headless Linux support. <code>juce_audio_processors_headless</code> provides the plug-in model without <code>juce_graphics</code>.</p><h3 id="host" tabindex="-1">Host <a class="header-anchor" href="#host" aria-label="Permalink to &quot;Host {#host}&quot;">​</a></h3><p>The application that loads plug-ins: a DAW such as Ableton Live, Logic, Pro Tools, or Reaper, or JUCE&#39;s own AudioPluginHost.</p><h2 id="i" tabindex="-1">I <a class="header-anchor" href="#i" aria-label="Permalink to &quot;I {#i}&quot;">​</a></h2><h3 id="introjucer" tabindex="-1">Introjucer <a class="header-anchor" href="#introjucer" aria-label="Permalink to &quot;Introjucer {#introjucer}&quot;">​</a></h3><p>The Projucer&#39;s predecessor, a project generator for the module format. It was merged into the Projucer in JUCE 4.2.</p><h2 id="j" tabindex="-1">J <a class="header-anchor" href="#j" aria-label="Permalink to &quot;J {#j}&quot;">​</a></h2><h3 id="jassert" tabindex="-1">jassert <a class="header-anchor" href="#jassert" aria-label="Permalink to &quot;jassert {#jassert}&quot;">​</a></h3><p>JUCE&#39;s debug-only assertion macro. When one fires, the comment above it usually explains what you did wrong.</p><h3 id="juceapplication" tabindex="-1">JUCEApplication <a class="header-anchor" href="#juceapplication" aria-label="Permalink to &quot;JUCEApplication {#juceapplication}&quot;">​</a></h3><p>The base class for a GUI application&#39;s lifecycle (<code>initialise</code>, <code>shutdown</code>, <code>systemRequestedQuit</code>, …). The <code>START_JUCE_APPLICATION</code> macro creates <code>main()</code> for you.</p><h3 id="juceheader" tabindex="-1">JuceHeader.h <a class="header-anchor" href="#juceheader" aria-label="Permalink to &quot;JuceHeader.h {#juceheader}&quot;">​</a></h3><p>A legacy convenience header that includes all of a project&#39;s modules. The Projucer generates it, and CMake does so via <code>juce_generate_juce_header</code>. Modern code usually includes module headers directly.</p><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L {#l}&quot;">​</a></h2><h3 id="latency" tabindex="-1">Latency <a class="header-anchor" href="#latency" aria-label="Permalink to &quot;Latency {#latency}&quot;">​</a></h3><p>The delay between sound entering and leaving the system. It is driven by the block size, the driver, and any look-ahead in your algorithm. Report algorithmic latency with <code>setLatencySamples()</code> so hosts can compensate.</p><h3 id="lookandfeel" tabindex="-1">LookAndFeel <a class="header-anchor" href="#lookandfeel" aria-label="Permalink to &quot;LookAndFeel {#lookandfeel}&quot;">​</a></h3><p>An object that draws the built-in widgets. Swap or subclass it (usually <code>LookAndFeel_V4</code>) to restyle an app without subclassing each widget.</p><h3 id="lv2" tabindex="-1">LV2 <a class="header-anchor" href="#lv2" aria-label="Permalink to &quot;LV2 {#lv2}&quot;">​</a></h3><p>An open, extensible plug-in standard, popular on Linux. JUCE 7 added authoring and hosting.</p><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M {#m}&quot;">​</a></h2><h3 id="message-thread" tabindex="-1">Message thread <a class="header-anchor" href="#message-thread" aria-label="Permalink to &quot;Message thread {#message-thread}&quot;">​</a></h3><p>The single thread that runs the event loop, GUI, timers, and most callbacks. Only this thread may touch <code>Component</code>s. → <a href="./../guide/core-concepts.html#threads">Threads</a></p><h3 id="messagemanager" tabindex="-1">MessageManager <a class="header-anchor" href="#messagemanager" aria-label="Permalink to &quot;MessageManager {#messagemanager}&quot;">​</a></h3><p>Runs the message loop. <code>MessageManager::callAsync()</code> queues a function to run on the message thread. <em>juce_events</em></p><h3 id="midi" tabindex="-1">MIDI / MIDI 2.0 / UMP <a class="header-anchor" href="#midi" aria-label="Permalink to &quot;MIDI / MIDI 2.0 / UMP {#midi}&quot;">​</a></h3><p>The Musical Instrument Digital Interface protocol. <code>MidiMessage</code> and <code>MidiBuffer</code> carry MIDI 1.0 events. MIDI 2.0 adds higher resolution and bidirectional negotiation (<strong>MIDI-CI</strong>), and uses <strong>Universal MIDI Packets</strong> (UMP). <em>juce_audio_basics, juce_midi_ci</em></p><h3 id="module" tabindex="-1">Module <a class="header-anchor" href="#module" aria-label="Permalink to &quot;Module {#module}&quot;">​</a></h3><p>A folder of JUCE source with one main header, a declaration block, and a few compile-unit <code>.cpp</code> files. The unit of dependency in JUCE. → <a href="./../guide/build-systems.html">Build systems</a></p><h3 id="mpe" tabindex="-1">MPE <a class="header-anchor" href="#mpe" aria-label="Permalink to &quot;MPE {#mpe}&quot;">​</a></h3><p>MIDI Polyphonic Expression, a convention for per-note pitch bend, pressure, and timbre by giving each note its own MIDI channel. Supported by <code>MPESynthesiser</code> and related classes.</p><h2 id="o" tabindex="-1">O <a class="header-anchor" href="#o" aria-label="Permalink to &quot;O {#o}&quot;">​</a></h2><h3 id="osc" tabindex="-1">OSC <a class="header-anchor" href="#osc" aria-label="Permalink to &quot;OSC {#osc}&quot;">​</a></h3><p>Open Sound Control, a network protocol for sending addressed control messages (<code>/synth/cutoff 0.5</code>) over UDP. <em>juce_osc</em></p><h3 id="oversampling" tabindex="-1">Oversampling <a class="header-anchor" href="#oversampling" aria-label="Permalink to &quot;Oversampling {#oversampling}&quot;">​</a></h3><p>Processing at a multiple of the sample rate to reduce aliasing in non-linear effects such as distortion. <code>dsp::Oversampling</code>.</p><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P {#p}&quot;">​</a></h2><h3 id="pace" tabindex="-1">PACE <a class="header-anchor" href="#pace" aria-label="Permalink to &quot;PACE {#pace}&quot;">​</a></h3><p>PACE Anti-Piracy, the company that owns JUCE (since 2020). It also makes iLok and the signing tools required for AAX.</p><h3 id="parameter" tabindex="-1">Parameter <a class="header-anchor" href="#parameter" aria-label="Permalink to &quot;Parameter {#parameter}&quot;">​</a></h3><p>A host-visible, automatable control of a plug-in, such as <code>AudioParameterFloat</code>. Its ID must stay stable across versions.</p><h3 id="pip" tabindex="-1">PIP <a class="header-anchor" href="#pip" aria-label="Permalink to &quot;PIP {#pip}&quot;">​</a></h3><p>Projucer Instant Project: a single header with a metadata block that tools turn into a full project. Most JUCE demos are PIPs.</p><h3 id="preparetoplay" tabindex="-1">prepareToPlay() <a class="header-anchor" href="#preparetoplay" aria-label="Permalink to &quot;prepareToPlay() {#preparetoplay}&quot;">​</a></h3><p>Called before processing starts, with the sample rate and maximum block size. Allocate and reset here, not in the audio callback.</p><h3 id="processblock" tabindex="-1">processBlock() <a class="header-anchor" href="#processblock" aria-label="Permalink to &quot;processBlock() {#processblock}&quot;">​</a></h3><p>The audio callback of an <code>AudioProcessor</code>. It receives an <code>AudioBuffer</code> (input and output, processed in place) and a <code>MidiBuffer</code>. It runs on the audio thread.</p><h3 id="projucer" tabindex="-1">Projucer <a class="header-anchor" href="#projucer" aria-label="Permalink to &quot;Projucer {#projucer}&quot;">​</a></h3><p>JUCE&#39;s GUI project manager and IDE exporter. It edits <code>.jucer</code> files. It is an alternative to CMake. → <a href="./../guide/build-systems.html#the-projucer">Build systems</a></p><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R {#r}&quot;">​</a></h2><h3 id="real-time-safe" tabindex="-1">Real-time safe <a class="header-anchor" href="#real-time-safe" aria-label="Permalink to &quot;Real-time safe {#real-time-safe}&quot;">​</a></h3><p>Code that finishes in bounded time: no locks that might wait, no allocation, no system calls with unbounded duration. Required on the audio thread.</p><h3 id="repaint" tabindex="-1">repaint() <a class="header-anchor" href="#repaint" aria-label="Permalink to &quot;repaint() {#repaint}&quot;">​</a></h3><p>Marks a component (or area) as needing a redraw. The actual <code>paint()</code> happens later, and multiple calls are merged.</p><h3 id="resized" tabindex="-1">resized() <a class="header-anchor" href="#resized" aria-label="Permalink to &quot;resized() {#resized}&quot;">​</a></h3><p>Called when a component&#39;s size changes. This is where you set the bounds of its children.</p><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S {#s}&quot;">​</a></h2><h3 id="sample-rate" tabindex="-1">Sample rate <a class="header-anchor" href="#sample-rate" aria-label="Permalink to &quot;Sample rate {#sample-rate}&quot;">​</a></h3><p>Samples per second per channel, commonly 44,100 or 48,000 Hz. It can change between <code>prepareToPlay()</code> calls, so never hard-code it.</p><h3 id="safepointer" tabindex="-1">SafePointer <a class="header-anchor" href="#safepointer" aria-label="Permalink to &quot;SafePointer {#safepointer}&quot;">​</a></h3><p><code>Component::SafePointer&lt;T&gt;</code>: a pointer to a component that automatically becomes null if the component is deleted. Use it in async callbacks.</p><h3 id="smoothedvalue" tabindex="-1">SmoothedValue <a class="header-anchor" href="#smoothedvalue" aria-label="Permalink to &quot;SmoothedValue {#smoothedvalue}&quot;">​</a></h3><p>Ramps a value to its target over a set time, to avoid clicks (&quot;zipper noise&quot;) when parameters jump.</p><h3 id="standalone" tabindex="-1">Standalone <a class="header-anchor" href="#standalone" aria-label="Permalink to &quot;Standalone {#standalone}&quot;">​</a></h3><p>A plug-in format target that wraps your plug-in in its own application window, with audio and MIDI settings.</p><h3 id="synthesiser" tabindex="-1">Synthesiser <a class="header-anchor" href="#synthesiser" aria-label="Permalink to &quot;Synthesiser {#synthesiser}&quot;">​</a></h3><p>A polyphonic synth framework: a <code>Synthesiser</code> owns <code>SynthesiserVoice</code>s, assigns incoming notes to them, and mixes their output.</p><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T {#t}&quot;">​</a></h2><h3 id="timer" tabindex="-1">Timer <a class="header-anchor" href="#timer" aria-label="Permalink to &quot;Timer {#timer}&quot;">​</a></h3><p>Calls <code>timerCallback()</code> on the message thread at a set interval. Ideal for polling audio-thread state to drive meters.</p><h3 id="tracktion" tabindex="-1">Tracktion <a class="header-anchor" href="#tracktion" aria-label="Permalink to &quot;Tracktion {#tracktion}&quot;">​</a></h3><p>The DAW Julian Storer wrote, from which JUCE was extracted. Its engine now lives on as the open-source Tracktion Engine, built on JUCE.</p><h2 id="u" tabindex="-1">U <a class="header-anchor" href="#u" aria-label="Permalink to &quot;U {#u}&quot;">​</a></h2><h3 id="undomanager" tabindex="-1">UndoManager <a class="header-anchor" href="#undomanager" aria-label="Permalink to &quot;UndoManager {#undomanager}&quot;">​</a></h3><p>Records <code>UndoableAction</code>s (and <code>ValueTree</code> changes you pass it to) into transactions that can be undone and redone. <em>juce_data_structures</em></p><h2 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V {#v}&quot;">​</a></h2><h3 id="valuetree" tabindex="-1">ValueTree <a class="header-anchor" href="#valuetree" aria-label="Permalink to &quot;ValueTree {#valuetree}&quot;">​</a></h3><p>A reference-counted tree of typed nodes with properties and children. It is observable, undoable, and serialisable, and it is JUCE&#39;s recommended model for app and plug-in state. <em>juce_data_structures</em></p><h3 id="var" tabindex="-1">var <a class="header-anchor" href="#var" aria-label="Permalink to &quot;var {#var}&quot;">​</a></h3><p>A variant type holding an int, double, bool, string, array, object, or binary data. It is used for <code>ValueTree</code> properties and JSON.</p><h3 id="vst3" tabindex="-1">VST3 <a class="header-anchor" href="#vst3" aria-label="Permalink to &quot;VST3 {#vst3}&quot;">​</a></h3><p>Steinberg&#39;s current plug-in format, supported on macOS, Windows, and Linux. Its SDK is bundled with JUCE and has been MIT-licensed since version 3.8.0.</p><h2 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W {#w}&quot;">​</a></h2><h3 id="webview-ui" tabindex="-1">WebView UI <a class="header-anchor" href="#webview-ui" aria-label="Permalink to &quot;WebView UI {#webview-ui}&quot;">​</a></h3><p>A plug-in or app interface written in HTML, CSS, and JavaScript, hosted in a <code>WebBrowserComponent</code> and bound to parameters via relays. Added in JUCE 8.</p><h3 id="wrapper" tabindex="-1">Wrapper <a class="header-anchor" href="#wrapper" aria-label="Permalink to &quot;Wrapper {#wrapper}&quot;">​</a></h3><p>The code in <code>juce_audio_plugin_client</code> that implements a plug-in format&#39;s API and forwards calls to your <code>AudioProcessor</code>.</p>',145)])])}const m=a(i,[["render",s]]);export{p as __pageData,m as default};
